  end

  @doc """
  Retrieve a user by ID

  Returns the user identified by `user`. The authenticated user must share
  at least one team with the target user; requests for users outside any
  shared team are rejected with 403.

  A user may always retrieve their own profile with this endpoint. Use the
  `GET /users/me` endpoint as a convenience alias for retrieving the
  authenticated user without specifying an ID.


  The requested user object.
  """
  @spec get(ArchAstro.SDK.Client.t(), String.t()) ::
          {:ok, ArchAstro.SDK.Types.User.t()} | {:error, ArchAstro.SDK.Error.reason()}
  def get(client, user) do
    path = "/api/v1/users/#{ArchAstro.SDK.Path.encode(user)}"
    ArchAstro.SDK.HTTP.request(client, :get, path, decode: {:ref, ArchAstro.SDK.Types.User})
  end

  @doc """
  List a user's artifacts

  Returns all artifacts owned by the specified user. Artifacts represent
  AI-generated or user-uploaded files associated with agent sessions,
  threads, or sandboxes — such as images, documents, and code outputs.

  The authenticated user must be requesting their own artifacts or must
  have administrative access. Attempting to list artifacts for a user
  the caller is not authorized to access returns 403.

  Results are returned in a single page without cursor pagination. Each
  artifact in the response reflects the state of its current version,
  including a short-lived signed `file_url` for direct download.


  Successful response
  """
  @spec artifacts(ArchAstro.SDK.Client.t(), String.t()) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1UsersUserArtifacts.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def artifacts(client, user) do
    path = "/api/v1/users/#{ArchAstro.SDK.Path.encode(user)}/artifacts"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1UsersUserArtifacts.Response}
    )
  end

  @doc """
  Create a user invite

  Creates a new invite for the authenticated user. The invite can optionally be
  scoped to a specific thread, a persona, or carry arbitrary metadata. The
  caller receives the new invite object at HTTP 201.

  The invite key is always generated server-side (192-bit URL-safe random
  string) and cannot be supplied by the caller.

  The path `:user` must match the authenticated user. If a `thread_id` is
  provided, the authenticated user must have permission to invite others to that
  thread; team threads are not supported and return an error. Supplying a
  `thread_id` that does not exist or that belongs to a different user returns
  an error. If a key collision occurs during creation the call returns a 409
  conflict — simply retry to generate a new key.


  The newly created invite object.
  """
  @spec invites(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.PostApiV1UsersUserInvites.Input.t()
        ) :: {:ok, ArchAstro.SDK.Types.UserInvite.t()} | {:error, ArchAstro.SDK.Error.reason()}
  def invites(client, user, input) do
    path = "/api/v1/users/#{ArchAstro.SDK.Path.encode(user)}/invites"

    ArchAstro.SDK.HTTP.request(client, :post, path,
      body: input,
      decode: {:ref, ArchAstro.SDK.Types.UserInvite}
    )
  end

  @doc """
  List organizations for a user

  Returns the organizations the specified user belongs to. A user can belong
  to at most one organization, so the `data` array contains either zero or one
  items.

  The authenticated viewer must have permission to inspect the target user.
  Returns an empty `data` array when the user has no organization membership.


  Successful response
  """
  @spec orgs(ArchAstro.SDK.Client.t(), String.t()) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1UsersUserOrgs.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def orgs(client, user) do
    path = "/api/v1/users/#{ArchAstro.SDK.Path.encode(user)}/orgs"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1UsersUserOrgs.Response}
    )
  end

  @doc """
  Update the current user's profile

  Updates one or more profile fields for the authenticated user. All
  fields are optional; omit any you do not want to change.

  When `profile_picture` is supplied, the image is uploaded and replaces
  the existing picture. The previous picture is deleted after the new one
  is stored. Image upload failures return 422 without modifying other
  profile fields.


  The user object with updated profile fields.
  """
  @spec profile(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.PutApiV1UsersUserProfile.Input.t()
        ) :: {:ok, ArchAstro.SDK.Types.User.t()} | {:error, ArchAstro.SDK.Error.reason()}
  def profile(client, user, input) do
    path = "/api/v1/users/#{ArchAstro.SDK.Path.encode(user)}/profile"

    ArchAstro.SDK.HTTP.request(client, :put, path,
      body: input,
      decode: {:ref, ArchAstro.SDK.Types.User}
    )
  end
end

defmodule ArchAstro.SDK.V1.Users.Tasks do
  @moduledoc """
  UserTask API resource.
  """

  @doc """
  List an owner's tasks

  Returns tasks owned by the specified user or team. You can narrow results using the
  optional filters below. By default results are returned in reverse chronological
  order (most recently created first); use `sort` and `order` to sort by due date or
  priority instead.

  User-authenticated callers may list their personal tasks or tasks for teams they
  have joined. Privileged callers provide the owner in the route; the owner's
  organization is implied by that principal. An explicit `org` is optional and,
  when set, must match the owner's organization.


  Successful response
  """
  @spec list(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.GetApiV1UsersUserTasks.Params.t()
        ) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1UsersUserTasks.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def list(client, user, params \\ %ArchAstro.SDK.Types.Operations.GetApiV1UsersUserTasks.Params{}) do
    path = "/api/v1/users/#{ArchAstro.SDK.Path.encode(user)}/tasks"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      query: params,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1UsersUserTasks.Response}
    )
  end

  @doc """
  Create a task for an owner

  Creates a new task owned by the specified user or team and returns the full
  task object. User-authenticated calls are attributed to the authenticated
  user or agent. App-scoped developer and server-to-server callers must provide
  the task's explicit `org` scope and an explicit `user` or `agent` actor for
  team tasks; a user-owned task reuses the user in the route unless an explicit
  agent is supplied. Every referenced principal is validated against the app,
  owner, and team membership before creation.


  The newly created task.
  """
  @spec create(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.PostApiV1UsersUserTasks.Input.t()
        ) :: {:ok, ArchAstro.SDK.Types.Task.t()} | {:error, ArchAstro.SDK.Error.reason()}
  def create(client, user, input) do
    path = "/api/v1/users/#{ArchAstro.SDK.Path.encode(user)}/tasks"

    ArchAstro.SDK.HTTP.request(client, :post, path,
      body: input,
      decode: {:ref, ArchAstro.SDK.Types.Task}
    )
  end

  @doc """
  List task blocker cycles

  Runs an on-demand diagnostic over unfinished tasks owned by the specified
  team or user and returns a forward cursor-paginated page of complete cyclic
  blocker components. Detection is bounded to owners with at most 100
  unfinished tasks. This endpoint is read-only: cycles do not prevent task
  updates, lease acquisition, or completion.


  Successful response
  """
  @spec blocker_cycles(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.GetApiV1UsersUserTasksBlockerCycles.Params.t()
        ) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1UsersUserTasksBlockerCycles.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def blocker_cycles(
        client,
        user,
        params \\ %ArchAstro.SDK.Types.Operations.GetApiV1UsersUserTasksBlockerCycles.Params{}
      ) do
    path = "/api/v1/users/#{ArchAstro.SDK.Path.encode(user)}/tasks/blocker_cycles"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      query: params,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1UsersUserTasksBlockerCycles.Response}
    )
  end

  @doc """
  List an owner's ready tasks

  Returns open tasks with no unfinished blockers and no active session lease.
  Readiness is calculated by the server from the current task projection. It is
  a snapshot, not a reservation; claim a task lease before starting work.

  Pass `explain=true` to include every open task with a stable readiness reason.


  Successful response
  """
  @spec ready(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.GetApiV1UsersUserTasksReady.Params.t()
        ) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1UsersUserTasksReady.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def ready(
        client,
        user,
        params \\ %ArchAstro.SDK.Types.Operations.GetApiV1UsersUserTasksReady.Params{}
      ) do
    path = "/api/v1/users/#{ArchAstro.SDK.Path.encode(user)}/tasks/ready"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      query: params,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1UsersUserTasksReady.Response}
    )
  end

  @doc """
  Search an owner's tasks

  Performs a full-text search over tasks owned by the specified user or team and returns
  matching results. Combine `q` with the optional filters to narrow the result set
  further. When no query is provided, the endpoint behaves like a filtered list.

  The `query` field in the response echoes the effective search query.
  User-authenticated callers may search their personal tasks or tasks for teams
  they have joined. Privileged callers provide the owner in the route; the owner's
  organization is implied by that principal. An explicit `org` is optional and,
  when set, must match the owner's organization.


  Successful response
  """
  @spec search(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.GetApiV1UsersUserTasksSearch.Params.t()
        ) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1UsersUserTasksSearch.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def search(
        client,
        user,
        params \\ %ArchAstro.SDK.Types.Operations.GetApiV1UsersUserTasksSearch.Params{}
      ) do
    path = "/api/v1/users/#{ArchAstro.SDK.Path.encode(user)}/tasks/search"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      query: params,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1UsersUserTasksSearch.Response}
    )
  end
end

defmodule ArchAstro.SDK.V1.Users.Threads do
  @moduledoc """
  UserThread API resource.
  """

  @doc """
  List threads for a user

  Returns all threads visible to the specified user. The authenticated caller must
  have access to the target user's account; a 403 is returned otherwise.

  Pass one or more `agent` IDs to narrow results to threads where at least one of
  the listed agents is also a member — useful for displaying every thread a user
  shares with a particular agent. Pass one or more `filter` objects to narrow
  results by thread metadata key/value pairs. Both narrowings may be combined in
  a single request.

  Results are returned as a flat array; no cursor-based pagination is applied.
  Threads are ordered with default threads first, then by most recent activity
  (newest first), each carrying a `last_activity` timestamp.


  Successful response
  """
  @spec list(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.GetApiV1UsersUserThreads.Params.t()
        ) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1UsersUserThreads.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def list(
        client,
        user,
        params \\ %ArchAstro.SDK.Types.Operations.GetApiV1UsersUserThreads.Params{}
      ) do
    path = "/api/v1/users/#{ArchAstro.SDK.Path.encode(user)}/threads"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      query: params,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1UsersUserThreads.Response}
    )
  end

  @doc """
  Create a thread for a user

  Creates a new thread owned by the specified user. The authenticated caller must
  have access to the target user's account; a 403 is returned otherwise.

  An automatic welcome message is sent into the thread upon creation unless
  `skip_welcome_message` is set to `true`. The thread is immediately visible to
  the owning user and any members added at creation time.


  The newly created thread object.
  """
  @spec create(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.PostApiV1UsersUserThreads.Input.t()
        ) :: {:ok, ArchAstro.SDK.Types.Thread.t()} | {:error, ArchAstro.SDK.Error.reason()}
  def create(client, user, input) do
    path = "/api/v1/users/#{ArchAstro.SDK.Path.encode(user)}/threads"

    ArchAstro.SDK.HTTP.request(client, :post, path,
      body: input,
      decode: {:ref, ArchAstro.SDK.Types.Thread}
    )
  end
end

defmodule ArchAstro.SDK.V1.Users.Tokens do
  @moduledoc """
  Token API resource.
  """

  @doc """
  List personal access tokens

  Returns all access tokens associated with the authenticated user, including
  active and revoked tokens. Tokens are returned without their raw JWT values
  — the plaintext JWT is only available at creation time.

  The caller must be the user identified by `user` and must present a
  first-party session (or a `full_access` access token).


  Successful response
  """
  @spec list(ArchAstro.SDK.Client.t(), String.t()) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1UsersUserTokens.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def list(client, user) do
    path = "/api/v1/users/#{ArchAstro.SDK.Path.encode(user)}/tokens"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1UsersUserTokens.Response}
    )
  end

  @doc """
  Create a personal access token

  Issues a new long-lived access token for the authenticated user. The raw
  JWT is returned in the `token` field of the response exactly once and
  cannot be retrieved again — store it securely immediately after creation.

  `scopes` is optional. When omitted the token receives `full_access`.
  Known catalog scopes (for example `profile`) restrict the token through
  the same `ScopeGuard` used by OAuth.

  `expires_in_days` is optional and must be one of `7`, `30`, `60`, `90`,
  or `365`. When omitted the token lasts 30 days. Each user may hold at
  most 50 active tokens; exceeding that limit returns 429.

  The caller must be the user identified by `user` and must present a
  first-party session (or a `full_access` access token). A restricted
  access token cannot mint another token.


  The newly created access token. The `token` field contains the raw JWT and is present only in this response — it is not stored and cannot be retrieved later.
  """
  @spec create(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.PostApiV1UsersUserTokens.Input.t()
        ) ::
          {:ok, ArchAstro.SDK.Types.SystemAccessToken.t()} | {:error, ArchAstro.SDK.Error.reason()}
  def create(client, user, input) do
    path = "/api/v1/users/#{ArchAstro.SDK.Path.encode(user)}/tokens"

    ArchAstro.SDK.HTTP.request(client, :post, path,
      body: input,
      decode: {:ref, ArchAstro.SDK.Types.SystemAccessToken}
    )
  end

  @doc """
  Revoke a personal access token

  Permanently revokes the specified access token belonging to the
  authenticated user. Once revoked, the token is immediately rejected by
  all API endpoints and cannot be reinstated. The token record is retained
  and returned in the response with `revoked_at` populated.

  The caller must be the user identified by `user` and must present a
  first-party session (or a `full_access` access token). Returns 404 if
  the token does not exist or does not belong to the caller.


  The revoked access token. The `revoked_at` field is populated with the time of revocation.
  """
  @spec delete(ArchAstro.SDK.Client.t(), String.t(), String.t()) ::
          {:ok, ArchAstro.SDK.Types.SystemAccessToken.t()} | {:error, ArchAstro.SDK.Error.reason()}
  def delete(client, user, token) do
    path =
      "/api/v1/users/#{ArchAstro.SDK.Path.encode(user)}/tokens/#{ArchAstro.SDK.Path.encode(token)}"

    ArchAstro.SDK.HTTP.request(client, :delete, path,
      decode: {:ref, ArchAstro.SDK.Types.SystemAccessToken}
    )
  end
end
